function findMinArrowShots(points: number[][]): number {
  // Сортируем по КОНЦУ шара.
  // В JS числа — double, поэтому a[1] - b[1] не переполняется (в Java/C++ это ловушка)
  points.sort((a, b) => a[1] - b[1]);

  let arrows = 1;
  // Первая стрела — в самый правый край шара, который кончается раньше всех
  let arrowX = points[0][1];

  for (let i = 1; i < points.length; i++) {
    const [start, end] = points[i];
    // Шар начинается правее текущей стрелы — она его не задевает, нужна новая
    if (start > arrowX) {
      arrows++;
      arrowX = end;
    }
    // Иначе start <= arrowX <= end (концы отсортированы) — шар уже лопнул
  }

  return arrows;
}

// Время: O(n log n) — сортировка
// Память: O(1) дополнительно (не считая сортировки)
